// Native offscreen validation of the production fragment shader. No windows.
#import <Foundation/Foundation.h>
#import <OpenGL/OpenGL.h>
#import <OpenGL/gl3.h>
static GLuint compile(GLenum type,NSString *src){GLuint s=glCreateShader(type);const char *p=src.UTF8String;glShaderSource(s,1,&p,0);glCompileShader(s);GLint ok;glGetShaderiv(s,GL_COMPILE_STATUS,&ok);if(!ok){char log[16000];glGetShaderInfoLog(s,sizeof(log),0,log);fprintf(stderr,"Shader: %s\n",log);exit(3);}return s;}
