 GLuint p=glCreateProgram();glAttachShader(p,compile(GL_VERTEX_SHADER,vert));glAttachShader(p,compile(GL_FRAGMENT_SHADER,frag));glLinkProgram(p);GLint ok;glGetProgramiv(p,GL_LINK_STATUS,&ok);if(!ok){char log[16000];glGetProgramInfoLog(p,sizeof(log),0,log);fprintf(stderr,"Link: %s\n",log);return 3;}glUseProgram(p);
